let (tx, mut rx) = tokio::sync::mpsc::channel::<Job>(1024);

tokio::spawn(async move {
    for job in source().await {
        tx.send(job).await.unwrap();   // awaits while full
    }
});

while let Some(job) = rx.recv().await {    // None = closed
    handle(job).await;
}
